import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Min reduction over the middle dimension of a contiguous 3D-like layout.
// Input viewed as [outer, R, inner]; output is [outer, inner].
// out[b, n] = min over r of in[b*R*inner + r*inner + n]
// Optimization: 4-way manual unroll over R with independent accumulators/pointers
// to increase memory-level parallelism and reduce the min dependency chain.
.visible .entry min_reduce_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 outer,
    .param .u32 R,
    .param .u32 inner
)
{
    .reg .pred %p<3>;
    .reg .b32 %r<24>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<12>;
    // n = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mul.lo.u32 %r3, %r1, %r2;
    mov.u32 %r4, %tid.x;
    add.u32 %r5, %r3, %r4;           // n
    ld.param.u32 %r6, [inner];
    setp.ge.u32 %p1, %r5, %r6;
    @%p1 bra DONE;                    // bounds check for partial blocks
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r7, [outer];
    ld.param.u32 %r8, [R];
    mov.u32 %r9, %ctaid.y;            // b
    // base element offset = b*R*inner + n
    mul.lo.u32 %r10, %r9, %r8;
    mul.lo.u32 %r11, %r10, %r6;
    add.u32 %r12, %r11, %r5;
    // running pointers = in_ptr + (base + k*inner)*4
    mul.wide.u32 %rd3, %r12, 4;
    add.u64 %rd4, %rd1, %rd3;         // p0
    // row stride in bytes = inner*4
    mul.wide.u32 %rd5, %r6, 4;
    add.u64 %rd8, %rd5, %rd5;         // 2*stride
    add.u64 %rd9, %rd8, %rd5;         // 3*stride
    add.u64 %rd10, %rd8, %rd8;        // 4*stride
    add.u64 %rd11, %rd4, %rd5;        // p1
    add.u64 %rd12, %rd4, %rd8;        // p2
    add.u64 %rd13, %rd4, %rd9;        // p3
    // four independent accumulators = +inf
    mov.f32 %f1, 0f7F800000;
    mov.f32 %f2, 0f7F800000;
    mov.f32 %f3, 0f7F800000;
    mov.f32 %f4, 0f7F800000;
    mov.u32 %r13, 0;                  // r = 0
    and.b32 %r14, %r8, 0xFFFFFFFC;    // R rounded down to multiple of 4
UNROLL_LOOP:
    setp.lt.u32 %p2, %r13, %r14;
    @!%p2 bra REM_CHECK;
    ld.global.f32 %f5, [%rd4];
    ld.global.f32 %f6, [%rd11];
    ld.global.f32 %f7, [%rd12];
    ld.global.f32 %f8, [%rd13];
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    add.u64 %rd4, %rd4, %rd10;
    add.u64 %rd11, %rd11, %rd10;
    add.u64 %rd12, %rd12, %rd10;
    add.u64 %rd13, %rd13, %rd10;
    add.u32 %r13, %r13, 4;
    bra UNROLL_LOOP;
REM_CHECK:
    setp.ge.u32 %p1, %r13, %r8;
    @%p1 bra END_LOOP;
REM_LOOP:
    setp.ge.u32 %p1, %r13, %r8;
    @%p1 bra END_LOOP;
    ld.global.f32 %f5, [%rd4];
    min.f32 %f1, %f1, %f5;
    add.u64 %rd4, %rd4, %rd5;
    add.u32 %r13, %r13, 1;
    bra REM_LOOP;
END_LOOP:
    min.f32 %f1, %f1, %f2;
    min.f32 %f1, %f1, %f3;
    min.f32 %f1, %f1, %f4;
    // out[b*inner + n] = accumulator
    mul.lo.u32 %r15, %r9, %r6;
    add.u32 %r16, %r15, %r5;
    mul.wide.u32 %rd6, %r16, 4;
    add.u64 %rd7, %rd2, %rd6;
    st.global.f32 [%rd7], %f1;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("min_reduce_kernel")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        """
        Initializes the model with the dimension to reduce over.

        Args:
            dim (int): The dimension to reduce over.
        """
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()

        ndim = x.dim()
        dim = self.dim
        if dim < 0:
            dim += ndim

        shape = x.shape
        outer = 1
        for i in range(dim):
            outer *= shape[i]
        R = shape[dim]
        inner = 1
        for i in range(dim + 1, ndim):
            inner *= shape[i]

        out_shape = list(shape[:dim]) + list(shape[dim + 1:])
        out = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        block_x = 256
        grid_x = (inner + block_x - 1) // block_x

        module.launch(
            "min_reduce_kernel",
            grid=(grid_x, outer, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, u32(outer), u32(R), u32(inner)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

